+            $tmp_name = $_FILES['imagen']['tmp_name'];
+            $original_name = basename($_FILES['imagen']['name']);
+            $extension = strtolower(pathinfo($original_name, PATHINFO_EXTENSION));
+            $allowed_extensions = ['jpg', 'jpeg', 'png', 'webp', 'gif'];
