+}
+
+// --- ACCIÓN 1: SUBIR NUEVA PUBLICACIÓN ---
+if (isset($_POST['agregar_post'])) {
+    $titulo = mysqli_real_escape_string($conn, $_POST['titulo'] ?? '');
+    $contenido = mysqli_real_escape_string($conn, $_POST['contenido'] ?? '');
