+                $filename = time() . '_' . uniqid() . '.' . $extension;
+                $destino = $upload_dir . $filename;
+
+                if (move_uploaded_file($tmp_name, $destino)) {
+                    $imagen_path = mysqli_real_escape_string($conn, $destino);
+                } else {
+                    $error_mensaje = "❌ No se pudo subir la imagen.";
